import re
for organizer_id in ('organizer-a', 'organizer-b'):
    pattern = rf'(<section class="page organizer" id="{organizer_id}">)(.*?)(</section>)'
    def move_illustration(match):
        body = match.group(2)
        figure = re.search(r'<figure class="action-strip .*?</figure>', body)
        if figure:
            body = body[:figure.start()] + body[figure.end():]
            body = body.replace('</h1>', '</h1>' + figure.group(0), 1)
        return match.group(1) + body + match.group(3)
    sections = re.sub(pattern, move_illustration, sections, flags=re.S)
