expert_text = '<p><b>Text:</b> The North Wind and the Sun. <b>Lens:</b> Character choices.</p><ol><li>The Wind uses force.</li><li>The traveler resists the cold.</li><li>The Sun changes the conditions.</li></ol><p><b>Two details:</b> In paragraph 2, stronger gusts make the traveler grip the cloak. In paragraph 3, warmth leads the traveler to remove it.</p><p><b>Summary:</b> The Wind and Sun compete. Force fails; warmth succeeds.</p><p><b>Interpretation:</b> Success depends on the task and the approach.</p><p><b>Question:</b> Does winning one test prove strength? <b>Vocabulary:</b> gust means a sudden rush of wind.</p>'
home_text = '<ul><li><b>Character:</b> Wind uses force; Sun uses warmth (paragraphs 2–3). Different choices produce different results.</li><li><b>Language:</b> “harder and harder” (paragraph 2). Repeated effort does not guarantee success.</li><li><b>Plot:</b> The tighter grip comes before the cloak is removed (paragraphs 2–3). The contrast makes the outcome clear.</li><li><b>Theme:</b> Warmth succeeds where force fails (paragraphs 2–3). Is the Sun stronger, or better suited to this test?</li></ul><p><b>Synthesis:</b> Character choices and plot show that an approach must fit the task. In paragraph 2, force increases resistance. In paragraph 3, warmth changes the result.</p><p><b>Next question:</b> What might the traveler say about this contest?</p>'
expert_sample = sample_notes('sample-expert-notes', '3–2–1 expert notes on character choices in the Aesop fable.', expert_text)
home_sample = sample_notes('sample-home-jigsaw', 'Home-group Jigsaw reports and synthesis for the Aesop fable.', home_text)
# Instructional continuations have room for worked examples below their text.
for section_id, sample in [('page-1', '<div class="sample-pair">' + expert_sample + home_sample + '</div>'), ('page-4', home_sample), ('page-7', expert_sample), ('organizer-a', expert_sample), ('organizer-b', home_sample)]:
    pattern = rf'(<section[^>]*id="{section_id}">)(.*?)(</section>)'
    def add_sample(match):
        body = match.group(2).replace('<footer>', sample + '<footer>', 1)
        return match.group(1) + body + match.group(3)
    sections = re.sub(pattern, add_sample, sections, flags=re.S)
